(()=>{
  const form=document.querySelector('[data-r31-prep-form]'); if(!form)return;
  const out=document.querySelector('[data-r31-prep-output]'),routesEl=document.querySelector('[data-r31-prep-routes]'),status=document.querySelector('[data-r31-prep-status]');
  const copy=document.querySelector('[data-r31-prep-copy]'),download=document.querySelector('[data-r31-prep-download]'),print=document.querySelector('[data-r31-prep-print]');
  const es=(document.documentElement.lang||'en').toLowerCase().startsWith('es'); let packet=null;
  const domains={
    safety:{en:'Safety / urgent help',es:'Seguridad / ayuda urgente',route:'/community-help-center/#urgent-help',evidence:['Emergency contact and safe-location plan','Key dates or incident time','Only non-sensitive facts needed for the next call'],questions:['Is anyone in immediate danger now?','Which official or crisis resource is appropriate first?']},
    legal:{en:'Legal / court preparation',es:'Preparación legal / tribunal',route:'/legal-help/',evidence:['Notices, letters or court papers you already possess','Timeline of important dates','Names of agencies/courts involved—without privileged narrative here'],questions:['Is there a stated deadline on a document?','Which Tennessee or local source should confirm procedure?','What questions should I take to a lawyer or legal-aid organization?']},
    health:{en:'Health / care navigation',es:'Salud / navegación de atención',route:'/health-help/',evidence:['Insurance card or coverage information kept privately','Medication list kept privately','Appointment/referral questions','Dates of recent care or notices'],questions:['Is emergency care needed now?','What care setting or provider type may fit?','What coverage/cost questions should I ask before scheduling?']},
    home:{en:'Home / property',es:'Vivienda / propiedad',route:'/home-property-help/',evidence:['Photos or estimates kept on your device','Permit/HOA/lease/contract documents you already have','Property/address facts to verify at the official source'],questions:['Is there an immediate safety issue?','Which permit, property or housing source controls?','What should a contractor, landlord, agent or attorney be asked?']},
    auto:{en:'Auto / vehicle',es:'Auto / vehículo',route:'/auto-vehicle-help/',evidence:['Repair estimates, photos and invoices kept privately','Vehicle/insurance documents kept privately','Dates of crash, repair, notice or purchase'],questions:['Is the vehicle safe to drive?','Is recall, insurance, repair, title or legal help the right starting point?','What should I ask a mechanic, insurer or attorney?']},
    insurance:{en:'Insurance / coverage / claim',es:'Seguro / cobertura / reclamo',route:'/community-help-center/',evidence:['Policy, plan, EOB, denial or claim correspondence kept privately','Claim/reference numbers and dates kept privately','Photos, estimates, receipts or provider bills kept privately when relevant'],questions:['What does the insurer or plan say in writing?','Is there a stated deadline, appeal, proof-of-loss or documentation request to confirm directly?','Which questions belong with the insurer/plan, provider/repairer, government source or attorney?']},
    transport:{en:'Transportation / mobility',es:'Transporte / movilidad',route:'/local-pathways/transportation-mobility/',evidence:['Broad trip needs and mobility accommodations','Pickup/destination area—not sensitive medical details'],questions:['Is accessible transportation needed?','Which current schedule/service area must be confirmed?']},
    senior:{en:'Senior / caregiver',es:'Adultos mayores / cuidadores',route:'/senior-caregiver/',evidence:['Broad care, transportation, benefits or home-support needs','Existing contacts and appointments kept privately'],questions:['Which needs overlap—health, home, benefits, legal, transportation?','Who should be included in the next conversation with permission?']},
    civic:{en:'Government / benefits / civic task',es:'Gobierno / beneficios / trámite cívico',route:'/get-it-done/',evidence:['Official notice or form name','Agency/department name if known','Dates and reference numbers kept privately'],questions:['Which official source owns this task?','Is eligibility, deadline, fee or appointment information current?']}
  };
  const labels={en:{title:'Franklin connected-needs preparation packet',none:'Choose at least one connected need.',first:'First actions',evidence:'What to gather privately',questions:'Questions to carry forward',handoff:'Professional or official handoff',privacy:'Privacy: this packet stays in this browser session unless you copy, print or download it. Do not type document text, medical details, privileged legal narratives, passwords or account numbers.',built:'Connected preparation packet built.',empty:'Choose at least one connected need before building the packet.',urgent:'Immediate danger selected: use 911 for immediate danger. Franklin Navigator does not dispatch responders.',soon:'Time-sensitive issue selected: confirm any changing deadline or official requirement directly at the relevant source.',normal:'No immediate danger selected.'},es:{title:'Paquete de preparación conectada de Franklin',none:'Elige al menos una necesidad relacionada.',first:'Primeros pasos',evidence:'Qué reunir de forma privada',questions:'Preguntas para llevar contigo',handoff:'Conexión con profesional o fuente oficial',privacy:'Privacidad: este paquete permanece en esta sesión del navegador salvo que lo copies, imprimas o descargues. No escribas texto de documentos, detalles médicos, narraciones legales confidenciales, contraseñas ni números de cuenta.',built:'Paquete de preparación conectado creado.',empty:'Elige al menos una necesidad relacionada antes de crear el paquete.',urgent:'Seleccionaste peligro inmediato: use 911 para peligro inmediato. Franklin Navigator no envía servicios de emergencia.',soon:'Seleccionaste un asunto urgente: confirme cualquier plazo o requisito cambiante directamente con la fuente responsable.',normal:'No seleccionaste peligro inmediato.'}}[es?'es':'en'];
  const selected=()=>[...form.querySelectorAll('input[name="need"]:checked')].map(x=>x.value).filter(x=>domains[x]);
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const intersections=needs=>{const set=new Set(needs),items=[];
    if(set.has('auto')&&set.has('insurance'))items.push(es?'Auto + seguro: separe seguridad del vehículo, fotos, estimados, comunicaciones del reclamo y preguntas sobre reparación o transporte; no interpretes cobertura aquí.':'Auto + insurance: separate vehicle safety, photos, estimates, claim communications, and repair/transport questions; do not interpret coverage here.');
    if(set.has('home')&&set.has('insurance'))items.push(es?'Vivienda + seguro: separe seguridad inmediata, mitigación, fotos, estimados, recibos y comunicaciones del reclamo; confirme requisitos directamente con la aseguradora.':'Home + insurance: separate immediate safety, mitigation, photos, estimates, receipts, and claim communications; confirm requirements directly with the insurer.');
    if(set.has('health')&&set.has('insurance'))items.push(es?'Salud + cobertura: conserve EOB, denegaciones y facturas en privado; confirme red, autorización, apelación y plazos directamente con el plan y proveedor.':'Health + coverage: keep EOBs, denials, and bills private; confirm network, authorization, appeal, and deadline details directly with the plan and provider.');
    if(set.has('legal')&&set.has('insurance'))items.push(es?'Legal + reclamo: conserva cartas, fechas, ofertas o liberaciones en privado y prepare preguntas antes de hacer declaraciones o firmar documentos que puedan tener consecuencias legales.':'Legal + claim: keep letters, dates, offers, or releases private and prepare questions before making statements or signing documents that may have legal consequences.');
    return items};
  const build=()=>{
    const needs=selected(); if(!needs.length){packet=null;out.innerHTML=`<p class="empty-state">${esc(labels.empty)}</p>`;routesEl.replaceChildren();status.textContent=labels.empty;window.FranklinProductHealth?.record('prep_empty_needs');return}
    const urgency=form.elements.urgency.value,stage=form.elements.stage.value;
    const urgencyText=urgency==='immediate'?labels.urgent:urgency==='soon'?labels.soon:labels.normal;
    const evidence=[...new Set(needs.flatMap(n=>domains[n].evidence))]; const questions=[...new Set(needs.flatMap(n=>domains[n].questions))]; const crossover=intersections(needs);
    packet={schemaVersion:'franklin.connected-preparation.device-only.v1',release:'FR-NAV1.8.0-CANDIDATE-R33',community:'FRANKLIN_TN',submissionStatus:'NOT_SENT',urgency,stage,needs,needLabels:needs.map(n=>domains[n][es?'es':'en']),firstActions:[urgencyText,es?'Separa los hechos, documentos, fechas y preguntas por necesidad relacionada.':'Separate facts, documents, dates and questions by connected need.',es?'Confirme información cambiante en la fuente oficial original antes de actuar.':'Confirm changing information at the original official source before acting.'],evidence,questions,routes:needs.map(n=>({label:domains[n][es?'es':'en'],url:domains[n].route})),directoryRoute:'/directory/',privacy:{narrativeCollected:false,documentUpload:false,networkSubmission:false,sensitiveTextRequested:false},intersections:crossover,externalEffects:{send:false,submit:false,file:false,schedule:false,pay:false},authorityTransfer:false};
    out.innerHTML=`<div class="eyebrow">${esc(labels.title)}</div><h3>${esc(packet.needLabels.join(' + '))}</h3>${urgency==='immediate'?`<p class="r31-safety">${esc(urgencyText)}</p>`:`<p><strong>${esc(labels.first)}:</strong> ${esc(urgencyText)}</p>`}<h3>${esc(labels.first)}</h3><ol>${packet.firstActions.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><h3>${esc(labels.evidence)}</h3><ul>${evidence.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>${esc(labels.questions)}</h3><ul>${questions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${crossover.length?`<h3>${es?'Conexiones importantes':'Important intersections'}</h3><ul>${crossover.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<p class="r31-privacy">${esc(labels.privacy)}</p>`;
    routesEl.replaceChildren();packet.routes.forEach(r=>{const a=document.createElement('a');a.href=r.url;a.innerHTML=`<span><strong>${esc(r.label)}</strong><span class=\"r32-link-note\">${es?'Confirma detalles cambiantes antes de actuar.':'Confirm changing details before acting.'}</span></span><span aria-hidden=\"true\">→</span>`;routesEl.append(a)});const d=document.createElement('a');d.href='/directory/';d.innerHTML=`<span><strong>${es?'Buscar organizaciones y profesionales locales':'Find local organizations and professionals'}</strong><span class=\"r32-link-note\">${es?'Los datos de contacto pueden cambiar; confirme antes de usar.':'Contact details can change; confirm before use.'}</span></span><span aria-hidden=\"true\">→</span>`;routesEl.append(d);
    status.textContent=labels.built;copy.disabled=download.disabled=print.disabled=false;window.FranklinProductHealth?.record('prep_packet_built');out.focus();
  };
  const qs=new URLSearchParams(location.search);const preNeeds=(qs.get('needs')||'').split(',').filter(Boolean);preNeeds.forEach(n=>{const el=form.querySelector(`input[name="need"][value="${CSS.escape(n)}"]`);if(el)el.checked=true});if(['normal','soon','immediate'].includes(qs.get('urgency')))form.elements.urgency.value=qs.get('urgency');
  form.addEventListener('submit',e=>{e.preventDefault();build()});form.addEventListener('reset',()=>setTimeout(()=>{packet=null;out.innerHTML=`<p class="empty-state">${esc(labels.empty)}</p>`;routesEl.replaceChildren();copy.disabled=download.disabled=print.disabled=true;status.textContent=''},0));
  copy.addEventListener('click',async()=>{if(!packet)return;try{await navigator.clipboard.writeText(JSON.stringify(packet,null,2));status.textContent=es?'Paquete copiado.':'Packet copied.'}catch{status.textContent=es?'No se pudo copiar automáticamente.':'We couldn’t copy that automatically.'}});
  download.addEventListener('click',()=>{if(!packet)return;const blob=new Blob([JSON.stringify(packet,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='franklin-connected-preparation.json';a.click();URL.revokeObjectURL(url);status.textContent=es?'Paquete descargado en su dispositivo.':'Packet downloaded to your device.'});
  print.addEventListener('click',()=>packet&&window.print());
  if(preNeeds.length)build();
})();
